{
  "name": "Rotrics DexArm 桌面机械臂",
  "name_en": "Rotrics DexArm Desktop Robotic Arm",
  "manufacturer": "Rotrics",
  "description": "DexArm 是一款桌面式多功能机械臂，可进行笛卡尔位置移动，并支持更换末端执行器，如笔夹、激光雕刻头、气动吸取模块和软夹爪等。它适用于教学、实验室自动化、简单搬运、绘图、激光加工及配合传送带或滑轨进行小型自动化任务。",
  "description_en": "The DexArm is a desktop multifunction robotic arm that performs Cartesian motion and supports interchangeable end effectors such as a pen holder, laser engraving head, pneumatic picker, and soft gripper. It is used for education, laboratory automation, simple handling, drawing, laser processing, and small-scale automation tasks with accessories like conveyor belts and sliding rails.",
  "actions": [
    {
      "action_name": "auto-go_home",
      "description": "机械臂回到原点并使能电机。",
      "description_en": "Return the robotic arm to its home position and enable the motors."
    },
    {
      "action_name": "auto-set_workorigin",
      "description": "将当前位置设为新的工作原点。",
      "description_en": "Set the current position as the new work origin."
    },
    {
      "action_name": "auto-set_acceleration",
      "description": "设置机械臂运动的加速度参数。",
      "description_en": "Set the acceleration parameters for robot motion."
    },
    {
      "action_name": "auto-set_module_type",
      "description": "定义末端执行器类型。",
      "description_en": "Define the type of end effector."
    },
    {
      "action_name": "auto-move_to",
      "description": "将机械臂移动到指定笛卡尔位置。",
      "description_en": "Move the robotic arm to a specified Cartesian position."
    },
    {
      "action_name": "auto-fast_move_to",
      "description": "将机械臂快速移动到指定笛卡尔位置。",
      "description_en": "Rapidly move the robotic arm to a specified Cartesian position."
    },
    {
      "action_name": "auto-dealy_ms",
      "description": "让机械臂任务队列暂停指定毫秒数。",
      "description_en": "Pause the robot command queue for a specified number of milliseconds."
    },
    {
      "action_name": "auto-dealy_s",
      "description": "让机械臂任务队列暂停指定秒数。",
      "description_en": "Pause the robot command queue for a specified number of seconds."
    },
    {
      "action_name": "auto-soft_gripper_pick",
      "description": "闭合软夹爪以抓取物体。",
      "description_en": "Close the soft gripper to grasp an object."
    },
    {
      "action_name": "auto-soft_gripper_place",
      "description": "张开软夹爪以放下物体。",
      "description_en": "Open the soft gripper wide to release an object."
    },
    {
      "action_name": "auto-soft_gripper_nature",
      "description": "将软夹爪释放到自然状态。",
      "description_en": "Release the soft gripper to its natural state."
    },
    {
      "action_name": "auto-soft_gripper_stop",
      "description": "停止软夹爪动作。",
      "description_en": "Stop soft gripper motion."
    },
    {
      "action_name": "auto-air_picker_pick",
      "description": "启动气动吸取模块以拾取物体。",
      "description_en": "Use the pneumatic picker to pick up an object."
    },
    {
      "action_name": "auto-air_picker_place",
      "description": "释放气动吸取模块所抓取的物体。",
      "description_en": "Release the object held by the pneumatic picker."
    },
    {
      "action_name": "auto-air_picker_nature",
      "description": "将气动吸取模块释放到自然状态。",
      "description_en": "Release the pneumatic picker to its natural state."
    },
    {
      "action_name": "auto-air_picker_stop",
      "description": "停止气动吸取模块动作。",
      "description_en": "Stop the pneumatic picker."
    },
    {
      "action_name": "auto-laser_on",
      "description": "开启激光模块。",
      "description_en": "Turn on the laser module."
    },
    {
      "action_name": "auto-laser_off",
      "description": "关闭激光模块。",
      "description_en": "Turn off the laser module."
    },
    {
      "action_name": "auto-conveyor_belt_forward",
      "description": "使传送带正向运行。",
      "description_en": "Move the conveyor belt forward."
    },
    {
      "action_name": "auto-conveyor_belt_backward",
      "description": "使传送带反向运行。",
      "description_en": "Move the conveyor belt backward."
    },
    {
      "action_name": "auto-conveyor_belt_stop",
      "description": "停止传送带。",
      "description_en": "Stop the conveyor belt."
    },
    {
      "action_name": "auto-sliding_rail_init",
      "description": "初始化滑轨附件。",
      "description_en": "Initialize the sliding rail accessory."
    },
    {
      "action_name": "auto-close",
      "description": "断开与机械臂的连接。",
      "description_en": "Disconnect from the robotic arm."
    }
  ],
  "tag_hints": [
    "desktop robotic arm",
    "laboratory automation",
    "pick and place",
    "laser engraving",
    "soft gripper",
    "vacuum picker",
    "conveyor automation",
    "sliding rail"
  ]
}

